// ValidateShareArtifactRequestBody runs the validations defined on
// ShareArtifactRequestBody
func ValidateShareArtifactRequestBody(body *ShareArtifactRequestBody) (err error) {
	if utf8.RuneCountInString(body.Repository) > 512 {
		err = goa.MergeErrors(err, goa.InvalidLengthError("body.repository", body.Repository, utf8.RuneCountInString(body.Repository), 512, false))
	}
	if utf8.RuneCountInString(body.Tag) > 128 {
		err = goa.MergeErrors(err, goa.InvalidLengthError("body.tag", body.Tag, utf8.RuneCountInString(body.Tag), 128, false))
	}
	if utf8.RuneCountInString(body.File) > 255 {
		err = goa.MergeErrors(err, goa.InvalidLengthError("body.file", body.File, utf8.RuneCountInString(body.File), 255, false))
	}
	return
}

